"""Protocol fixtures generated by merged main, before preparing/caching ring keys."""

import json
import unittest
from pathlib import Path

from bandersnatch_vrfs import (
    RingContext,
    ietf_vrf_sign,
    ietf_vrf_verify,
    public_from_secret,
    secret_from_seed,
    vrf_output,
)


class TestLegacyCompatibility(unittest.TestCase):
    @classmethod
    def setUpClass(cls):
        root = Path(__file__).resolve().parents[1]
        cls.ring_data = (root / 'data/zcash-srs-2-11-uncompressed.bin').read_bytes()
        cls.cases = json.loads((root / 'test/legacy_compatibility.json').read_text())['cases']
        cls.secrets = [secret_from_seed(i.to_bytes(8, 'little')) for i in range(1023)]
        cls.publics = [public_from_secret(secret) for secret in cls.secrets]

    def test_legacy_commitments_and_ring_proofs(self):
        for case in self.cases:
            with self.subTest(profile=case['label']):
                context = RingContext(
                    self.ring_data, self.publics[:case['count']],
                    ring_capacity=case['capacity'],
                )
                self.assertEqual(bytes.fromhex(case['commitment']), context.commitment)
                signature = bytes.fromhex(case['ring_signature'])
                self.assertEqual(784, len(signature))
                self.assertEqual(
                    bytes.fromhex(case['output']),
                    context.ring_vrf_verify(b'legacy-compatibility', b'aux', signature),
                )

    def test_legacy_ietf_signature_bytes_and_outputs(self):
        for case in self.cases:
            with self.subTest(profile=case['label']):
                index = case['index']
                signature = bytes.fromhex(case['ietf_signature'])
                expected = bytes.fromhex(case['output'])
                self.assertEqual(96, len(signature))
                self.assertEqual(signature, ietf_vrf_sign(
                    self.secrets[index], b'legacy-compatibility', b'aux',
                ))
                self.assertEqual(expected, ietf_vrf_verify(
                    self.publics[index], b'legacy-compatibility', b'aux', signature,
                ))
                self.assertEqual(expected, vrf_output(
                    self.secrets[index], b'legacy-compatibility',
                ))
